// Each pair changes one control or one instant. Values use the lesson's displayed units.
function pair(question, pregunta, first, second, phaseA, phaseB, explanation, explicacion) {
  return {question: {en: question, es: pregunta}, first, second, phaseA, phaseB,
    explanation: {en: explanation, es: explicacion}};
}

